import 'package:cloud_firestore/cloud_firestore.dart';
import 'model_utils.dart';
class RecommendationModel { const RecommendationModel({required this.id,required this.studentId,required this.majorId,required this.matchPercentage,required this.reasons,required this.createdAt,this.strengths=const [],this.weaknesses=const []}); final String id,studentId,majorId; final double matchPercentage; final List<String> reasons,strengths,weaknesses; final DateTime createdAt; factory RecommendationModel.fromFirestore(DocumentSnapshot<Map<String,Object?>> d)=>RecommendationModel(id:d.id,studentId:d['studentId'] as String,majorId:d['majorId'] as String,matchPercentage:(d['matchPercentage'] as num).toDouble(),reasons:stringsFrom(d['reasons']),strengths:stringsFrom(d['strengths']),weaknesses:stringsFrom(d['weaknesses']),createdAt:dateFromValue(d['createdAt'])!); Map<String,Object?> toFirestore()=>{'studentId':studentId,'majorId':majorId,'matchPercentage':matchPercentage,'reasons':reasons,'strengths':strengths,'weaknesses':weaknesses,'createdAt':Timestamp.fromDate(createdAt)}; }
